return ['domain'=>'publishpress-authors(n%100<10 || n%100>=20) ? 1 : 2);','plural-forms'=>'nplurals=3; plural=(n == 1 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 10:05+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'PublishPress Authors umożliwia dodawanie wielu autorów oraz autorów gościnnych do postów WordPress','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'Przejdź na wersję Pro','This plugin can be deleted.'=>'Ten plugin można usunąć.','Actions provided by PublishPress plugins.'=>'Akcje udostępnione przez wtyczki PublishPress.','List Authors'=>'Lista Autorów','Lists PublishPress Authors. Results never include author email addresses.'=>'Wyświetla autorów PublishPress. Wyniki nie zawierają adresów e-mail autorów.','Get Author'=>'Pobierz Autora','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'Pobiera jednego autora PublishPress na podstawie ID terminu. Odpowiedź nigdy nie zawiera adresu e-mail.','Get Post Authors'=>'Pobierz Autorów Postów','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'Pobiera uporządkowanych autorów PublishPress przypisanych do jednego edytowalnego posta. Odpowiedź nigdy nie zawiera adresów e-mail autorów.','Get Author Fields'=>'Pobierz Pola Autora','Lists enabled author-profile field definitions without exposing profile values.'=>'Wyświetla zdefiniowane pola profilu autora bez ujawniania wartości profilu.','Author not found.'=>'Autor nie został znaleziony.','Post not found.'=>'Post nie został znaleziony.','Authors List'=>'Lista Autorów','Display authors list.'=>'Wyświetl listę autorów.','Title'=>'Tytuł','Layout'=>'Układ','Display All Authors (including those who have not written any posts)'=>'Wyświetl wszystkich autorów (w tym tych, którzy nie napisali żadnych postów)','Enable author\'s search box'=>'Włącz pole wyszukiwania autora','Limits per page'=>'Limity na stronie','Authors'=>'Autorzy','Order'=>'Kolejność','Order by'=>'Sortuj według','Grid Columns'=>'Kolumny siatki','Author\'s search box field (Seperate multiple fields by comma(\',\'))'=>'Pole wyszukiwania autora (Oddziel wiele pól przecinkiem(\',\'))','All Authors'=>'Wszyscy Autorzy','Guest Authors'=>'Autorzy Gościnni','Users Authors'=>'Autorzy Użytkowników','Ascending'=>'Rosnąco','Descending'=>'Malejąco','Name'=>'Imię','Post Counts'=>'Liczba Postów','First Name'=>'Imię','Last Name'=>'Nazwisko','Showing authors starting with %s'=>'Wyświetlanie autorów zaczynających się na %s','Showing all authors'=>'Pokazywanie wszystkich autorów','No authors found.'=>'Nie znaleziono autorów.','Loading authors...'=>'Ładowanie autorów...','Unable to load authors.'=>'Nie można załadować autorów.','Default Search'=>'Domyślne wyszukiwanie','Search Box'=>'Pole wyszukiwania','Search'=>'Szukaj','Search authors'=>'Szukaj autorów','Search authors by'=>'Szukaj autorów według','No recent posts from this author'=>'Brak ostatnich postów od tego autora','Request status.'=>'Status żądania.','Security error. Kindly reload this page and try again'=>'Błąd zabezpieczeń. Proszę przeładować tę stronę i spróbować ponownie','You cannot edit an author profile linked to an administrator account.'=>'Nie możesz edytować profilu autora powiązanego z kontem administratora.','You do not have permission to edit this author profile because it is linked to a user account you do not have permission to edit.'=>'Nie masz uprawnień do edytowania tego profilu autora, ponieważ jest on powiązany z kontem użytkownika, którego nie masz uprawnień edytować.','Sorry, this WordPress user is already mapped to another Author. By default, each user can only be connected to one Author profile.'=>'Przykro mi, ten użytkownik WordPress jest już powiązany z innym autorem. Domyślnie każdy użytkownik może być połączony tylko z jednym profilem autora.','Registered User is required.'=>'Wymagany zarejestrowany użytkownik.','Author URL cannot be empty.'=>'URL autora nie może być pusty.','Another user with Author URL already exists.'=>'Inny użytkownik z URL-em autora już istnieje.','Author name is required'=>'Nazwa autora jest wymagana','No post ID provided for Authors_Iterator constructor. Are you not in a loop or is $post not set?'=>'Nie podano ID postu dla konstruktora Authors_Iterator. Czy nie jesteś w pętli, czy $post nie jest ustawiony?','Display name publicly as'=>'Wyświetl nazwę publicznie jako','Email'=>'Email','Author Type'=>'Typ autora','Guest Author With User Account'=>'Autor gościnny z kontem użytkownika','Registered Author With User Account'=>'Zarejestrowany autor z kontem użytkownika','Guest Author With No User Account'=>'Autor gościnny bez konta użytkownika','Edit User'=>'Edytuj użytkownika','Edit Author Profile'=>'Edytuj profil autora','Create Author Profile'=>'Utwórz profil autora','General'=>'Ogólne','Avatar'=>'Awatar','Author'=>'Autor','Registered User'=>'Zarejestrowany użytkownik','Biographical Info'=>'Informacje biograficzne','Avatar Source'=>'Źródło awatara','Default Avatar'=>'Domyślny awatar','(Uses the %1$s Email field %2$s to find the Gravatar account if default avatar is not uploaded in Authors Settings)'=>'(Używa pola %1$s Email %2$s do znalezienia konta Gravatar, jeśli domyślny awatar nie został przesłany w Ustawieniach autorów)','Custom image'=>'Obrazek niestandardowy','Alternative Text'=>'Tekst alternatywny','Describe the avatar. Leave blank to use the Media Library alternative text or author name.'=>'Opisz awatar. Pozostaw puste, aby użyć tekstu alternatywnego z biblioteki mediów lub nazwy autora.','Decorative Image'=>'Obraz dekoracyjny','Use empty alternative text when this avatar is decorative.'=>'Użyj pustego tekstu alternatywnego, gdy ten awatar jest dekoracyjny.','Website'=>'Strona internetowa','Author Category'=>'Kategoria autora','Select the default Category for this Author. This will be used when the Author is added to new posts.'=>'Wybierz domyślną kategorię dla tego autora. Będzie to używane, gdy autor zostanie dodany do nowych postów.','Do not show this profile publicly'=>'Nie pokazuj tego profilu publicznie','(required)'=>'(wymagane)','Select image'=>'Wybierz obraz','Remove this image'=>'Usuń ten obraz','Select a user'=>'Wybierz użytkownika','Author email error'=>'Błąd e-maila autora','Create an author profile for a current user account. You can select users who are allowed to edit posts. This user will be able to update their profile.'=>'Utwórz profil autora dla bieżącego konta użytkownika. Możesz wybrać użytkowników, którzy mają prawo edytować posty. Ten użytkownik będzie mógł zaktualizować swój profil.','Create an author profile and a linked user account. This account will be in the "Guest Author" role and will not be able to login to the WordPress dashboard or update their profile.'=>'Utwórz profil autora i powiązane konto użytkownika. To konto będzie miało rolę "Gościnnego autora" i nie będzie mogło zalogować się do pulpitu WordPress ani zaktualizować swojego profilu.','Create an author profile with no linked user account. This option is lightweight but may have compatibility issues with other themes and plugins.'=>'Utwórz profil autora bez powiązanego konta użytkownika. Ta opcja jest lekka, ale może mieć problemy z kompatybilnością z innymi motywami i wtyczkami.','Author Email'=>'E-mail autora','User Account'=>'Konto użytkownika','Sync author and user fields'=>'Synchronizuj pola autora i użytkownika','Convert to Guest Author With User Account'=>'Konwertuj na Gościnnego autora z kontem użytkownika','Update post count'=>'Aktualizuj liczbę postów','No authors were updated'=>'Nie zaktualizowano autorów','Updated %d authors'=>'Zaktualizowano %d autorów','An author with the name provided already exists.'=>'Autor o podanej nazwie już istnieje.','An author email is required when creating new User Author.'=>'E-mail autora jest wymagany podczas tworzenia nowego użytkownika autora.','This email address is already linked to another WordPress user.'=>'Ten adres e-mail jest już powiązany z innym użytkownikiem WordPress.','Now inspecting or updating %d total authors'=>'Teraz sprawdzam lub aktualizuję %d łącznie autorów','%1$d/%2$d: Inspecting the user %3$d'=>'%1$d/%2$d: Sprawdzam użytkownika %3$d','All is set. No author need to be updated'=>'Wszystko jest ustawione. Nie ma autorów do zaktualizowania','Now inspecting or updating %d total posts'=>'Teraz sprawdzam lub aktualizuję %d łącznie postów','%1$d/%2$d: Inspecting the post %3$d'=>'%1$d/%2$d: Sprawdzam post %3$d','Creating author term for the user %d'=>'Tworzenie terminu autora dla użytkownika %d','Adding the author term %1$d to the post %2$d'=>'Dodawanie terminu autora %1$d do postu %2$d','All is set. No posts need to be updated'=>'Wszystko jest ustawione. Nie ma postów do zaktualizowania','Configure'=>'Konfiguruj','Please correct your form errors below and try again.'=>'Proszę poprawić błędy formularza poniżej i spróbować ponownie.','Cheatin&#8217; uh?'=>'Oszuści&#8217; huh?','You do not have necessary permissions to complete this action.'=>'Nie masz niezbędnych uprawnień do wykonania tej akcji.','Post does not exist'=>'Post nie istnieje','No author term'=>'Brak terminu autora','"post_author" is empty'=>'"post_author" jest pusty','Drag-and-drop Authors to add them to the %s category'=>'Przeciągnij i upuść autorów, aby dodać ich do kategorii %s','Search for an author'=>'Szukaj autora','This option is showing because you do not have a WordPress user selected as an author. For some tasks, it can be helpful to have a user selected here. This user will not be visible on the front of your site.'=>'Ta opcja jest wyświetlana, ponieważ nie masz wybranego użytkownika WordPress jako autora. W przypadku niektórych zadań pomocne może być wybranie tutaj użytkownika. Ten użytkownik nie będzie widoczny na froncie Twojej strony.','Search for an user'=>'Szukaj użytkownika','Author Box'=>'Box autora','Default Author Box'=>'Domyślny box autora','Hide Author Box'=>'Ukryj box autora','Filter posts by author'=>'Filtruj posty według autora','Remove %s'=>'Usuń %s','New author added.'=>'Nowy autor dodany.','Author profile deleted.'=>'Profil autora usunięty.','Author profile updated.'=>'Profil autora zaktualizowany.','Error adding author account.'=>'Błąd podczas dodawania konta autora.','Error updating author profile.'=>'Błąd podczas aktualizacji profilu autora.','Authors deleted.'=>'Autorzy usunięci.','Author URL'=>'URL autora','Co-Authors Plus must be installed and active.'=>'Co-Authors Plus musi być zainstalowany i aktywny.','Read more.'=>'Czytaj więcej.','The results could not be loaded.'=>'Wyniki nie mogły zostać załadowane.','Please delete %d character'=>'Proszę usunąć %d znak','Please delete %d characters'=>'Proszę usunąć %d znaków','Please enter %d or more character'=>'Proszę wpisać %d lub więcej znak','Please enter %d or more characters'=>'Proszę wpisać %d lub więcej znaków','Loading more results...'=>'Ładowanie większej ilości wyników...','You can only select %d item'=>'Możesz wybrać tylko %d element','You can only select %d items'=>'Możesz wybrać tylko %d elementów','No results found'=>'Nie znaleziono wyników','Searching...'=>'Szukam...','Remove all items'=>'Usuń wszystkie elementy','No results match'=>'Brak pasujących wyników','Need PublishPress Authors Support?'=>'Potrzebujesz wsparcia PublishPress Authors?','If you need help or have a new feature request, let us know.'=>'Jeśli potrzebujesz pomocy lub masz nowe zapytanie dotyczące funkcji, daj nam znać.','Request Support'=>'Złóż prośbę o wsparcie','Detailed documentation is also available on the plugin website.'=>'Szczegółowa dokumentacja jest również dostępna na stronie wtyczki.','View Knowledge Base'=>'Zobacz bazę wiedzy','Text'=>'Tekst','Multiline text'=>'Tekst wieloliniowy','WYSIWYG Editor'=>'Edytor WYSIWYG','Link'=>'Link','Email address'=>'Adres e-mail','Active'=>'Aktywny','Disabled'=>'Wyłączone','Optional'=>'Opcjonalne','Required'=>'Wymagane','No'=>'Nie','Yes, this is a Social Profile'=>'Tak, to jest profil społecznościowy','Select an option'=>'Wybierz opcję','dofollow'=>'dofollow','nofollow'=>'nofollow','Discover authors, categories and boxes for a post byline'=>'Odkryj autorów, kategorie i pola dla podpisu postu','Read paginated existing author term IDs and enabled author categories plus native Author Box choices for one editable post. Uses byline permissions rather than granting profile management. Never creates profiles for unassigned WordPress users. Follow each list total_pages separately.'=>'Przeczytaj paginowane istniejące identyfikatory terminów autorów i włączone kategorie autorów oraz natywne opcje Autor Box dla jednego edytowalnego postu. Używa uprawnień do podpisu zamiast przyznawania zarządzania profilem. Nigdy nie tworzy profili dla nieprzypisanych użytkowników WordPress. Śledź każdą listę total_pages osobno.','Read post authors and Author Box'=>'Przeczytaj autorów postów oraz Autor Box','Read exact ordered author term IDs, author-category assignments, fallback WordPress author and per-post Author Box with a revision hash. Requires native byline and edit_post permissions; never guesses author IDs or writes during reads.'=>'Przeczytaj dokładne uporządkowane identyfikatory terminów autorów, przypisania autor-kategoria, zapasowy autor WordPress i Autor Box dla każdego postu z hashem rewizji. Wymaga natywnych uprawnień do podpisu i edit_post; nigdy nie zgaduje identyfikatorów autorów ani nie pisze podczas odczytu.','Update post authors and Author Box'=>'Zaktualizuj autorów postów oraz Autor Box','Replace a post byline with ordered author_ids, or patch category assignments and its Author Box. Omitted fields are preserved. Requires the latest hash and an enabled post type. dry_run previews without saving. Discover authors, categories and native layout choices first.'=>'Zastąp podpis postu uporządkowanymi identyfikatorami autorów, lub popraw przypisania kategorii oraz jego Autor Box. Pominięte pola są zachowywane. Wymaga najnowszego hasha i włączonego typu postu. dry_run przegląda bez zapisywania. Najpierw odkryj autorów, kategorie i natywne opcje układu.','Update bylines on multiple posts'=>'Zaktualizuj podpisy na wielu postach','Apply explicit per-post byline changes after validating every object, revision hash and author/category identifier. Each change has its own post_id and expected_hash. dry_run previews all targets without saving. On failure, prior writes are compensated with their original bylines.'=>'Zastosuj wyraźne zmiany w podpisie dla każdego postu po walidacji każdego obiektu, hasha rewizji i identyfikatora autora/kategorii. Każda zmiana ma swoje własne post_id i expected_hash. dry_run przegląda wszystkie cele bez zapisywania. W przypadku niepowodzenia wcześniejsze zapisy są rekompensowane ich oryginalnymi podpisami.','Choose a post type enabled for Authors.'=>'Wybierz typ postu włączony dla autorów.','The post byline changed. Read it again before saving.'=>'Podpis postu został zmieniony. Przeczytaj go ponownie przed zapisaniem.','Choose existing author term IDs.'=>'Wybierz istniejące identyfikatory terminów autorów.','Empty bylines must first be enabled in Authors settings.'=>'Puste podpisy muszą najpierw być włączone w ustawieniach autorów.','Category assignments must refer to the selected authors.'=>'Przypisania kategorii muszą odnosić się do wybranych autorów.','Multiple author categories are disabled.'=>'Wiele kategorii autorów jest wyłączonych.','Choose an enabled author category available for this post type.'=>'Wybierz włączoną kategorię autora dostępną dla tego typu postu.','An empty byline preserves its existing fallback WordPress author.'=>'Pusty podpis zachowuje swojego istniejącego zapasowego autora WordPress.','Choose an existing fallback WordPress user.'=>'Wybierz istniejącego użytkownika zapasowego WordPress.','Choose an available Author Box and enable per-post box selection.'=>'Wybierz dostępny Autor Box i włącz wybór pola na poziomie postu.','The byline save failed and its original state could not be restored. Read the post before retrying.'=>'Zapis podpisu nie powiódł się i jego oryginalny stan nie mógł zostać przywrócony. Przeczytaj post przed ponowną próbą.','Could not save the complete post byline.'=>'Nie można zapisać pełnego podpisu postu.','Include each post only once in a batch.'=>'Uwzględnij każdy post tylko raz w partii.','The batch failed and some original bylines could not be restored. Read all target posts before retrying.'=>'Partia nie powiodła się i niektóre oryginalne podpisy nie mogły zostać przywrócone. Przeczytaj wszystkie docelowe posty przed ponowną próbą.','List Author Categories'=>'Lista kategorii autorów','Read native author category IDs, singular/plural names, order, enabled state and schema settings. These group a post byline and differ from post categories. Pro adds per-post-type targeting. Results are paginated.'=>'Przeczytaj natywne identyfikatory kategorii autorów, nazwy w liczbie pojedynczej/mnogiej, kolejność, stan włączenia oraz ustawienia schematu. Te grupują podpis postu i różnią się od kategorii postów. Pro dodaje celowanie na poziomie typu postu. Wyniki są paginowane.','Discover Author Category fields'=>'Odkryj pola kategorii autorów','Read category identifiers, label and grouping settings, and active-edition targeting choices. Categories describe author byline roles such as Writer or Reviewer, not WordPress post categories.'=>'Przeczytaj identyfikatory kategorii, etykiety i ustawienia grupowania oraz wybory celowania w aktywnej edycji. Kategorie opisują role podpisu autora, takie jak Pisarz lub Recenzent, a nie kategorie postów WordPress.','Read Author Category'=>'Przeczytaj kategorię autora','Read one verified native author category and revision hash. Use this hash when updating or deleting.'=>'Przeczytaj jedną zweryfikowaną natywną kategorię autora i hash rewizji. Użyj tego hasha podczas aktualizacji lub usuwania.','Create or update Author Category'=>'Utwórz lub zaktualizuj kategorię autora','Create a category with category_name and plural_name or patch an existing ID using expected_hash. Preserves omitted fields, validates post types and requires Pro for post-type targeting. dry_run previews without saving. Category order is an integer position.'=>'Utwórz kategorię z category_name i plural_name lub popraw istniejący identyfikator używając expected_hash. Zachowuje pominięte pola, waliduje typy postów i wymaga Pro do celowania w typ postu. dry_run przegląda bez zapisywania. Kolejność kategorii to pozycja całkowita.','Delete unused Author Category'=>'Usuń nieużywaną kategorię autora','Delete an unused native category and its metadata. Existing post category relationships or author-profile defaults must be reassigned first. Requires expected_hash; dry_run checks without deleting.'=>'Usuń nieużywaną natywną kategorię oraz jej metadane. Istniejące relacje kategorii postów lub domyślne profile autorów muszą być najpierw przypisane ponownie. Wymaga expected_hash; dry_run sprawdza bez usuwania.','Singular name'=>'Nazwa pojedyncza','Plural name'=>'Nazwy mnogie','Schema property'=>'Właściwość schematu','Author Category not found.'=>'Kategoria autora nie została znaleziona.','The category changed. Read it again before saving.'=>'Kategoria została zmieniona. Przeczytaj to ponownie przed zapisaniem.','Use exact category field types from discovery.'=>'Użyj dokładnych typów pól kategorii z odkrycia.','Singular and plural category names are required.'=>'Wymagana jest nazwa kategorii w liczbie pojedynczej i mnogiej.','Category post-type targeting requires Authors Pro.'=>'Celowanie w typ postu kategorii wymaga Authors Pro.','Choose registered post types.'=>'Wybierz zarejestrowane typy postów.','An Author Category with this slug already exists.'=>'Kategoria autora z tym slugiem już istnieje.','Could not save the native Author Category.'=>'Nie można zapisać natywnej kategorii autora.','The category save failed; the original state was restored.'=>'Zapis kategorii nie powiódł się; oryginalny stan został przywrócony.','The category save failed and restoration was incomplete. Read it before retrying.'=>'Zapis kategorii nie powiódł się, a przywracanie było niekompletne. Przeczytaj to przed ponowną próbą.','The category changed. Read it again before deleting.'=>'Kategoria została zmieniona. Przeczytaj to ponownie przed usunięciem.','Reassign category references before deleting.'=>'Przypisz referencje do kategorii przed usunięciem.','The category could not be deleted.'=>'Kategoria nie mogła zostać usunięta.','Use the exact native field type shown in discovery.'=>'Użyj dokładnego natywnego typu pola pokazanego w odkryciu.','Choose a list of values from field discovery.'=>'Wybierz listę wartości z odkrycia pola.','Field choice lists require string values from discovery.'=>'Listy wyboru pól wymagają wartości typu string z odkrycia.','Box shortcodes require parallel lists of shortcode and position strings.'=>'Shortcode\'y boków wymagają równoległych list stringów shortcode i pozycji.','Box shortcodes require string values.'=>'Shortcode\'y boków wymagają wartości typu string.','Each box shortcode needs one matching position.'=>'Każdy shortcode boksu potrzebuje jednej odpowiadającej pozycji.','The native field sanitizer is unavailable.'=>'Natywny sanitariusz pól jest niedostępny.','List saved Author Lists'=>'Zapisane listy autorów','Read a bounded page of saved Author List presets. Each preset has its own ID and shortcode. This is configuration, not a list of author profiles. Includes native active/trash status.'=>'Przeczytaj ograniczoną stronę zapisanych presetów list autorów. Każdy preset ma swój własny identyfikator i shortcode. To jest konfiguracja, a nie lista profili autorów. Zawiera natywny status aktywny/śmieci.','Read saved Author List'=>'Przeczytaj zapisaną listę autorów','Read one verified list preset, its shortcode and revision hash. Editing a list does not change author profiles, post bylines or Author Boxes.'=>'Przeczytaj jeden zweryfikowany preset listy, jego shortcode i hash rewizji. Edytowanie listy nie zmienia profili autorów, podpisów postów ani boxów autora.','Discover Author List fields'=>'Odkryj pola listy autorów','Read native layout, display-field, grouping, image, filter and active-edition search/pagination choices. Pro-only controls appear only with Pro active; promotional controls are excluded.'=>'Przeczytaj natywne opcje układu, pola wyświetlania, grupowania, obrazu, filtrowania i wyborów wyszukiwania/paginacji aktywnej edycji. Kontrole tylko dla Pro pojawiają się tylko przy aktywnym Pro; kontrolki promocyjne są wyłączone.','Create or update Author List'=>'Utwórz lub zaktualizuj listę autorów','Create a list with native title and layout fields, or patch a verified preset using its latest hash. Generates a native publishpress_authors_list shortcode from validated fields. Preserves omitted fields and other lists. Use status active to restore a trashed preset. dry_run previews without saving.'=>'Utwórz listę z natywnymi polami tytułu i układu, lub zaktualizuj zweryfikowany preset używając jego najnowszego hasha. Generuje natywny shortcode publishpress_authors_list z walidowanych pól. Zachowuje pominięte pola i inne listy. Użyj statusu aktywnego, aby przywrócić usunięty preset. dry_run podgląda bez zapisywania.','Trash or delete Author List'=>'Kosz lub usuń listę autorów','Trash a verified saved list, or explicitly use permanent true to remove its preset. Requires the latest hash. Does not delete posts or author profiles. dry_run checks without saving.'=>'Koszuj zweryfikowaną zapisaną listę, lub użyj jawnie permanentnego true, aby usunąć jej preset. Wymaga najnowszego hasha. Nie usuwa postów ani profili autorów. dry_run sprawdza bez zapisywania.','Author List not found.'=>'Lista autorów nie została znaleziona.','The Author List changed. Read it again before saving.'=>'Lista autorów została zmieniona. Przeczytaj to ponownie przed zapisaniem.','An Author List requires a title and native layout.'=>'Lista autorów wymaga tytułu i natywnego układu.','The Author List changed. Read it again before deleting.'=>'Lista autorów została zmieniona. Przeczytaj to ponownie przed usunięciem.','List Author Boxes'=>'Listuj boxy autorów','Read Author Box'=>'Przeczytaj box autora','Discover Author Box fields'=>'Odkryj pola boxu autora','Save Author Box'=>'Zapisz pole autora','Trash Author Box'=>'Kosz pole autora','List author field definitions'=>'Lista definicji pól autora','Read author field definition'=>'Przeczytaj definicję pola autora','Discover custom field options'=>'Odkryj opcje pola custom field','Save author field definition'=>'Zapisz definicję pola autora','Trash author field definition'=>'Kosz definicji pola autora','New boxes only: choose a native Free or Pro template from field discovery.'=>'Tylko nowe pudełka: wybierz natywny szablon Free lub Pro z odkrywania pól.','List a bounded page of native objects with IDs, titles, slugs and status. Only editable objects are returned. Read the exact object and its field schema before editing. Follow total_pages even if permissions filter a page to empty.'=>'Lista ograniczonej strony natywnych obiektów z identyfikatorami, tytułami, slugami i statusem. Zwracane są tylko edytowalne obiekty. Przeczytaj dokładny obiekt i jego schemat pola przed edytowaniem. Śledź total_pages, nawet jeśli uprawnienia filtrują stronę na pustą.','Read a verified native object with its editable settings and revision hash. Does not expose arbitrary post metadata. Custom field definitions are distinct from author profile values.'=>'Przeczytaj zweryfikowany natywny obiekt z jego edytowalnymi ustawieniami i hashem wersji. Nie ujawnia dowolnych metadanych postu. Definicje pól custom field są odrębne od wartości profilu autora.','Discover native editor labels, field types, supported choices and edition-specific fields. Optional id selects an existing object. Unknown or inactive-edition fields are rejected during saves.'=>'Odkryj etykiety edytora natywnego, typy pól, wspierane wybory i pola specyficzne dla edycji. Opcjonalne id wybiera istniejący obiekt. Nieznane lub nieaktywne pola edycji są odrzucane podczas zapisywania.','Create a native object or patch a verified ID using discovered typed fields. New objects need a title and default to draft. Updates require expected_hash, preserve omitted fields and use native sanitizers. dry_run validates without saving. menu_order controls native list ordering. Managing custom field definitions requires Pro.'=>'Utwórz natywny obiekt lub zaktualizuj zweryfikowany identyfikator, używając odkrytych typowanych pól. Nowe obiekty potrzebują tytułu i domyślnie są szkicami. Aktualizacje wymagają expected_hash, zachowują pominięte pola i używają natywnych sanitizatorów. dry_run waliduje bez zapisywania. menu_order kontroluje kolejność listy natywnej. Zarządzanie definicjami pól custom field wymaga Pro.','Trash a verified native object with delete_post permission and expected_hash. Does not permanently delete it when Trash is disabled. Existing references are not rewritten. dry_run checks without deleting; custom field deletion requires Pro.'=>'Kosz zweryfikowanego natywnego obiektu z uprawnieniem delete_post i expected_hash. Nie usuwa go permanentnie, gdy Kosz jest wyłączony. Istniejące odniesienia nie są przepisane. dry_run sprawdza bez usuwania; usunięcie pola custom field wymaga Pro.','Field Type'=>'Typ pola','Field Status'=>'Status pola','Required or optional'=>'Wymagane lub opcjonalne','Social Profile'=>'Profil społecznościowy','Link relationship'=>'Relacja linku','Open link in a new tab'=>'Otwórz link w nowej karcie','Show in REST API'=>'Pokaż w REST API','Description'=>'Opis','Native object not found.'=>'Natywny obiekt nie został znaleziony.','This object changed. Read it again before editing.'=>'Ten obiekt się zmienił. Przeczytaj go ponownie przed edytowaniem.','A title is required for a new object.'=>'Tytuł jest wymagany dla nowego obiektu.','You cannot create or publish this native object.'=>'Nie możesz utworzyć ani opublikować tego natywnego obiektu.','This field name is reserved for account identity or security.'=>'Ta nazwa pola jest zarezerwowana dla tożsamości konta lub bezpieczeństwa.','Choose a unique author field slug.'=>'Wybierz unikalny slug pola autora.','Choose discovered profile field names for the box order.'=>'Wybierz odkryte nazwy pól profilu dla kolejności pudełka.','Choose a discovered template when creating a new Author Box.'=>'Wybierz odkryty szablon podczas tworzenia nowego pola autora.','The field order could not be saved. Read the object before retrying.'=>'Kolejność pól nie mogła zostać zapisana. Przeczytaj obiekt przed ponowną próbą.','Native metadata save failed; the original object was restored.'=>'Zapis metadanych natywnych nie powiódł się; oryginalny obiekt został przywrócony.','Native metadata save failed and the original object could not be fully restored. Read it before retrying.'=>'Zapis metadanych natywnych nie powiódł się i oryginalny obiekt nie mógł zostać w pełni przywrócony. Przeczytaj go przed ponowną próbą.','This object changed. Read it again before deleting.'=>'Ten obiekt się zmienił. Przeczytaj go ponownie przed usunięciem.','You cannot trash this object, or Trash is disabled.'=>'Nie możesz przenieść tego obiektu do kosza, lub Kosz jest wyłączony.','The native object could not be trashed.'=>'Natywny obiekt nie mógł zostać przeniesiony do kosza.','Discover author profile fields'=>'Odkryj pola profilu autora','Read native field labels, types and choices for an author. Enabled custom fields are included. Email, account identity, passwords and privileged user fields are excluded from profile fields; account linking has a separate action.'=>'Przeczytaj etykiety pól natywnych, typy i wybory dla autora. Włączone pola custom są uwzględnione. E-maile, tożsamość konta, hasła i pola użytkowników z przywilejami są wyłączone z pól profilu; łączenie kont ma osobną akcję.','Read author profile details'=>'Przeczytaj szczegóły profilu autora','Read an author profile, public native field values and a revision hash. Hidden REST fields, emails and arbitrary metadata are excluded. Use get-profile-fields before editing and the latest hash to update.'=>'Przeczytaj profil autora, publiczne wartości pól natywnych i hash wersji. Ukryte pola REST, e-maile i dowolne metadane są wyłączone. Użyj get-profile-fields przed edytowaniem i najnowszego hasha do aktualizacji.','Create or update author profile'=>'Utwórz lub zaktualizuj profil autora','Create a guest author, create a profile linked to an existing user_id, or patch an existing profile. Guest creation must be enabled. Discover native fields first; update requires expected_hash. Preserves omitted fields and respects linked-user permissions and administrator profile locks. dry_run validates without saving. Does not create WordPress accounts.'=>'Utwórz gościnnego autora, utwórz profil powiązany z istniejącym user_id lub zaktualizuj istniejący profil. Tworzenie gości musi być włączone. Najpierw odkryj pola natywne; aktualizacja wymaga expected_hash. Zachowuje pominięte pola i respektuje uprawnienia powiązanego użytkownika oraz blokady profilu administratora. dry_run waliduje bez zapisywania. Nie tworzy kont WordPress.','Link or unlink an author user account'=>'Połącz lub odłącz konto użytkownika autora','Link an existing author to an existing WordPress user, or use user_id 0 to unlink without deleting or changing the account. Requires the latest profile hash, edit_user on linked accounts, native mapping restrictions and administrator profile policy. dry_run previews without saving.'=>'Połącz istniejącego autora z istniejącym użytkownikiem WordPress, lub użyj user_id 0, aby odłączyć bez usuwania lub zmiany konta. Wymaga najnowszego hasha profilu, edit_user na powiązanych kontach, ograniczeń mapowania natywnego oraz polityki profilu administratora. dry_run podgląda bez zapisywania.','Delete an unassigned author profile'=>'Usuń profil autora bez przypisania','Delete a verified, unassigned author profile using native taxonomy permissions. Reassign existing posts first. Never deletes its linked WordPress account. Requires the latest profile hash; dry_run checks without deleting.'=>'Usuń zweryfikowany, nieprzypisany profil autora przy użyciu natywnych uprawnień taksonomii. Najpierw przypisz istniejące posty. Nigdy nie usuwa powiązanego konta WordPress. Wymaga najnowszego hasha profilu; dry_run sprawdza bez usuwania.','The author changed. Read the profile again before saving.'=>'Autor został zmieniony. Przeczytaj profil ponownie przed zapisaniem.','You cannot edit the linked user account.'=>'Nie możesz edytować powiązanego konta użytkownika.','Editing other administrator profiles is disabled.'=>'Edycja innych profili administratorów jest wyłączona.','Choose an existing user for a new profile; use link-author-user to remap an existing author.'=>'Wybierz istniejącego użytkownika dla nowego profilu; użyj link-author-user, aby przemapować istniejącego autora.','This user already has an author profile.'=>'Ten użytkownik ma już profil autora.','Choose an editable media attachment for the avatar.'=>'Wybierz edytowalny załącznik multimedialny dla awatara.','Guest author creation requires a name and must be enabled in Authors settings.'=>'Tworzenie gościnnego autora wymaga imienia i musi być włączone w ustawieniach Autorów.','A linked author uses the WordPress account nicename as its slug.'=>'Powiązany autor używa nicename konta WordPress jako swojego slug.','Choose a unique, non-empty author slug.'=>'Wybierz unikalny, niepusty slug autora.','Profile field save failed; the original state was restored.'=>'Zapis pola profilu nie powiódł się; przywrócono oryginalny stan.','Profile field save failed and restoration was incomplete. Read the profile before retrying.'=>'Zapis pola profilu nie powiódł się, a przywracanie było niekompletne. Przeczytaj profil przed ponowną próbą.','The user is already mapped to another author.'=>'Użytkownik jest już przypisany do innego autora.','You cannot delete this author profile.'=>'Nie możesz usunąć tego profilu autora.','Reassign posts before deleting this author profile.'=>'Przypisz posty przed usunięciem tego profilu autora.','Could not delete the author profile.'=>'Nie udało się usunąć profilu autora.','The settings could not be saved. Read them again before retrying.'=>'Ustawienia nie mogły zostać zapisane. Przeczytaj je ponownie przed ponowną próbą.','Read Authors settings'=>'Przeczytaj ustawienia Autorów','Read typed General, Display, Author Pages, Guest Authors and Advanced settings, with defaults and native layout/role/post-type choices. Credentials and license keys are excluded. Whole-module switches use list-features and set-feature-enabled.'=>'Przeczytaj wprowadzone ustawienia ogólne, wyświetlanie, strony autorów, gościnnych autorów i zaawansowane ustawienia, z domyślnymi i natywnymi opcjami układu/roli/typów postów. Poświadczenia i klucze licencyjne są wyłączone. Przełączniki całego modułu używają list-features i set-feature-enabled.','Update Authors settings'=>'Zaktualizuj ustawienia Autorów','Patch only supplied Authors settings; preserves unrelated settings. Use get-plugin-settings for exact fields and native choices. dry_run validates and returns proposed values without saving. Author Pages changes refresh rewrite rules. Pro branding requires Pro.'=>'Zaktualizuj tylko dostarczone ustawienia Autorów; zachowuje niepowiązane ustawienia. Użyj get-plugin-settings, aby uzyskać dokładne pola i natywne opcje. dry_run waliduje i zwraca proponowane wartości bez zapisywania. Zmiany stron autorów odświeżają reguły przepisywania. Pro branding wymaga Pro.','Discover Authors features and actions'=>'Odkryj funkcje i działania Autorów','List native Authors screens/modules, enabled state, permissions, edition and read/write workflows. Separate author profiles, post bylines, Author Boxes, Author Lists, Author Categories and Pro Custom Fields. Use field discovery before editing.'=>'Wyświetl natywne ekrany/moduły Autorów, stan włączony, uprawnienia, edycję oraz przepływy pracy odczytu/zapisu. Oddzielne profile autorów, nagłówki postów, Pudełka Autorów, Listy Autorów, Kategorie Autorów oraz Pro Pola niestandardowe. Użyj odkrywania pól przed edytowaniem.','Enable or disable an Authors module'=>'Włącz lub wyłącz moduł Autorów','Change one discovered optional module switch. Autoloaded/core modules cannot be disabled. Does not change individual feature settings or author fields. dry_run previews without saving; refresh the MCP connection after enabling a module.'=>'Zmień jeden odkryty opcjonalny przełącznik modułu. Moduły autoloaded/core nie mogą być wyłączone. Nie zmienia ustawień pojedynczych funkcji ani pól autorów. dry_run podgląda bez zapisywania; odśwież połączenie MCP po włączeniu modułu.','Show Author Box below content'=>'Pokaż Pudełko Autora poniżej treści','Show Author Box above content'=>'Pokaż Pudełko Autora powyżej treści','Force empty author'=>'Wymuś pustego autora','Username in search field'=>'Nazwa użytkownika w polu wyszukiwania','Enable plugin author pages'=>'Włącz strony autorów wtyczki','Show author pages bio'=>'Pokaż biografię stron autorów','Show author post featured image'=>'Pokaż wyróżniony obrazek postu autora','Link author post featured image'=>'Połącz wyróżniony obrazek postu autora','Show author post excerpt'=>'Pokaż fragment postu autora','Remove single user map restriction'=>'Usuń ograniczenie mapy pojedynczego użytkownika','Show author post authors'=>'Pokaż autorów postów autora','Show author post date'=>'Pokaż datę publikacji autora','Show author post comments'=>'Pokaż komentarze autora','Show author post category'=>'Pokaż kategorię autora','Show author post tags'=>'Pokaż tagi autora','Show author post readmore'=>'Pokaż więcej autorów','Hide author pages empty posts message'=>'Ukryj wiadomość o pustych postach autora','Show author page title'=>'Pokaż tytuł strony autora','Disable quick edit author box'=>'Wyłącz szybki edytor pola autora','Enable font awesome'=>'Włącz Font Awesome','Allow guest authors without a user account'=>'Zezwól gościnnym autorom na brak konta użytkownika','Author boxes opt out'=>'Rezygnacja z pól autorów','Allow author multiple categories'=>'Zezwól autorowi na wiele kategorii','Allow guest authors with a user account'=>'Zezwól gościnnym autorom z kontem użytkownika','Show editor author box selection'=>'Pokaż wybór pola autora w edytorze','Default avatar decorative'=>'Domyślne dekoracyjne awatary','Translate author taxonomy'=>'Tłumacz taxonomy autora','Allow administrators to edit other administrator profiles'=>'Zezwól administratorom na edytowanie profili innych administratorów','Show email link in legacy Author Box'=>'Pokaż link e-mail w starym polu autora','Show website link in legacy Author Box'=>'Pokaż link do strony w starym polu autora','Legacy Author Box color scheme'=>'Schemat kolorów starego pola autora','Choose a native Author Box layout ID or slug from discovery.'=>'Wybierz identyfikator układu lub slug natywnego pola autora z odkrycia.','List'=>'Lista','Grid'=>'Siatka','Positive pixel size, or an empty string to use the native image size.'=>'Dodatni rozmiar piksela lub pusty ciąg, aby użyć natywnego rozmiaru obrazu.','Pro: display PublishPress branding.'=>'Pro: wyświetl markę PublishPress.','Roles available when mapping existing WordPress users to authors.'=>'Role dostępne podczas mapowania istniejących użytkowników WordPress na autorów.','Automatically create author profiles for new users in these roles.'=>'Automatycznie twórz profile autorów dla nowych użytkowników w tych rolach.','Default author taxonomy term ID for new posts; zero uses native defaults.'=>'Domyślny identyfikator terminu taxonomy autora dla nowych postów; zero używa natywnych domyślnych ustawień.','Existing WordPress user ID used as the core post author for guest bylines.'=>'Istniejący identyfikator użytkownika WordPress używany jako główny autor postu dla gościnnych autorów.','Native guest account setting. MCP profile actions only link existing accounts and never create user accounts.'=>'Ustawienia natywnego konta gościnnego. Działania profilu MCP łączą tylko istniejące konta i nigdy nie tworzą kont użytkowników.','Posts per author page: -1 shows all posts; zero uses the native default of 10.'=>'Posty na stronie autora: -1 pokazuje wszystkie posty; zero używa domyślnego ustawienia 10.','Use exact setting types from discovery.'=>'Użyj dokładnych typów ustawień z odkrycia.','Role lists require role-name strings from discovery.'=>'Listy ról wymagają ciągów nazw ról z odkrycia.','Post type switches require true or false.'=>'Przełączniki typu postu wymagają wartości prawda lub fałsz.','This post type is enabled by site code and cannot be disabled here.'=>'Ten typ postu jest włączony przez kod witryny i nie może być tutaj wyłączony.','Choose an existing default author profile.'=>'Wybierz istniejący domyślny profil autora.','Choose an existing fallback user.'=>'Wybierz istniejącego użytkownika zapasowego.','Choose a valid avatar URL.'=>'Wybierz ważny adres URL awatara.','Native settings validation failed.'=>'Walidacja natywnych ustawień nie powiodła się.','Author Boxes'=>'Pola autorów','Author Lists'=>'Listy autorów','Author Categories'=>'Kategorie autorów','Author field definitions'=>'Definicje pól autora','Settings, Author Pages and integrations'=>'Ustawienia, strony autorów i integracje','Author profiles'=>'Profile autorów','Ordered post bylines and per-post Author Box'=>'Zamówione podpisy postów i pole autora na każdy post','Choose a discovered optional module.'=>'Wybierz odkryty opcjonalny moduł.','Edit My Author Profile'=>'Edytuj mój profil autora','This name is used in several default displays and some search engine integrations.'=>'Ta nazwa jest używana w kilku domyślnych wyświetleniach i niektórych integracjach z wyszukiwarkami.','This forms part of the URL for the author’s profile page. If you choose a Mapped User, this URL is taken from the user’s account and can not be changed.'=>'To jest część URL strony profilu autora. Jeśli wybierzesz użytkownika zamapowanego, ten URL jest pobierany z konta użytkownika i nie może być zmieniony.','Search Authors'=>'Szukaj autorów','Popular Authors'=>'Popularni autorzy','Parent Author'=>'Autor nadrzędny','Parent Author:'=>'Autor nadrzędny:','Edit Author'=>'Edytuj autora','View Author'=>'Zobacz autora','Update Author'=>'Zaktualizuj autora','New Author Profile'=>'Nowy profil autora','New Author'=>'Nowy autor','Separate authors with commas'=>'Oddziel autorów przecinkami','Add or remove authors'=>'Dodaj lub usuń autorów','Choose from the most used Authors'=>'Wybierz z najczęściej używanych autorów','Back to Authors'=>'Powrót do autorów','If you like %1$s please leave us a %2$s rating. Thank you!'=>'Jeśli podoba się %1$s, zostaw nam ocenę %2$s. Dziękujemy!','Posts'=>'Posty','Published posts of the following post types: %s'=>'Opublikowane posty następujących typów postów: %s','Click on an author to change them. Drag to change their order.'=>'Kliknij na autora, aby go zmienić. Przeciągnij, aby zmienić ich kolejność.','No co-author exists for that term'=>'Nie istnieje współautor dla tego terminu','Edit'=>'Edytuj','Add Author'=>'Dodaj autora','Are you sure you want to remove this author?'=>'Czy na pewno chcesz usunąć tego autora?','Click to change this author, or drag to change their position'=>'Kliknij, aby zmienić tego autora, lub przeciągnij, aby zmienić 